const K='meeting-points-admin-drafts',read=()=>JSON.parse(localStorage.getItem(K)||'[]'),safe=s=>String(s||'').replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const placement=()=>`<style>.admin-placement{border:0;border-top:1px dotted #bcc4ee;margin:24px 0;padding:24px 0 0;display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.admin-placement legend{font-size:1.35rem;font-weight:700;margin-bottom:16px}.admin-placement label{position:relative;margin:0}.admin-placement input{position:absolute;opacity:0}.admin-placement label span{display:grid;gap:4px;height:100%;box-sizing:border-box;border:1px solid #c8cffb;border-radius:15px;padding:14px;cursor:pointer}.admin-placement small{color:#727a9d}.admin-placement input:checked+span{background:#273cff;color:#fff}.admin-placement input:checked+span small{color:#dfe3ff}.admin-placement input:disabled+span{opacity:.38;cursor:not-allowed}.admin-placement>p{grid-column:1/-1;margin:0;color:#737b9c;font-size:.8rem}@media(max-width:650px){.admin-placement{grid-template-columns:1fr}}</style><fieldset class="admin-placement"><legend>Onde entra?</legend><label><input type="radio" name="placement" value="none" checked><span><strong>Arquivo</strong><small>Apenas na coleção</small></span></label><label><input type="radio" name="placement" value="frequency"><span><strong>Na frequência</strong><small>Destaque principal</small></span></label><label><input type="radio" name="placement" value="radar"><span><strong>Top 5</strong><small>No meu radar</small></span></label><p>Só notas 9 ou 10 podem virar destaque.</p></fieldset>`;
export function adminPage(){const items=read();return `<section class="admin-shell"><header class="admin-intro"><a href="./#inicio">← meeting.points</a><span class="eyebrow">ESTÚDIO EDITORIAL</span><h1>Nova review.</h1><p>Você escreve. O catálogo completa o resto.</p><div class="admin-steps"><span class="active">1 · Review</span><span>2 · Dados oficiais</span><span>3 · Publicação</span></div></header><div class="admin-grid"><form class="admin-form" id="admin-form"><section><h2>Qual disco?</h2><div class="admin-row"><label>Nome do álbum<input name="title" required placeholder="Ex.: Untrue"></label><label>Artista<input name="artist" required placeholder="Ex.: Burial"></label></div></section><section><div class="admin-score-head"><h2>Sua leitura</h2><label>Nota<select name="score" required><option value="">—</option>${Array.from({length:11},(_,i)=>`<option>${i}</option>`).join('')}</select><span>/ 10</span></label></div><label>Primeiras impressões<textarea name="review" required rows="4" placeholder="Pode escrever livremente. A home receberá uma chamada curta automática."></textarea></label><label>Review completa<textarea name="body" required rows="12" placeholder="Escreva ou cole o texto completo…"></textarea></label></section>${placement()}<div class="admin-auto"><strong>Preenchimento automático</strong><p>Capa, artista, lançamento, formato, gênero, selo, fotos, ficha lateral, faixas, créditos, duração e links serão pesquisados ao publicar.</p></div><div class="admin-actions"><button class="solid" type="submit">Salvar rascunho</button><button class="publish-current" type="button">Buscar dados e publicar ↗</button></div><p class="admin-status" role="status"></p></form><aside class="admin-drafts"><div class="section-head"><h2>Rascunhos</h2><span>${items.length}</span></div>${items.map((d,i)=>`<article class="draft-card"><button data-draft="${i}"><strong>${safe(d.title)||'Sem título'}</strong><span>${safe(d.artist)||'Artista'}</span></button><button data-publish="${i}">Completar e publicar ↗</button></article>`).join('')||'<div class="admin-empty"><span>○</span><p>Seu próximo disco começa aqui.</p></div>'}</aside></div></section>`}
async function publish(d,status,button){if(!d.title||!d.artist||!d.review||!d.body||d.score==='')return status.textContent='Preencha álbum, artista, nota e os dois textos.';if(+d.score<9)d.placement='none';button.disabled=true;status.textContent='Buscando capa, perfil, faixas e dados oficiais…';try{const r=await fetch('/api/admin/reviews',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(d)}),x=await r.json();if(!r.ok)throw Error(x.error||'Não foi possível publicar.');status.innerHTML=`Review publicada. <a href="./#album/${x.id}">Abrir no site ↗</a>`;button.textContent='Publicado ✓'}catch(e){status.textContent=e.message;button.disabled=false}}
export function bindAdmin(root){const f=root.querySelector('#admin-form'),status=root.querySelector('.admin-status'),data=()=>Object.fromEntries(new FormData(f)),score=f.elements.score,featured=[...f.querySelectorAll('[name=placement]')].filter(x=>x.value!=='none');const gate=()=>{const allowed=+score.value>=9;featured.forEach(x=>{x.disabled=!allowed;if(!allowed&&x.checked)f.elements.placement.value='none'});root.querySelector('.admin-placement').classList.toggle('is-locked',!allowed)};score.onchange=gate;gate();f.onsubmit=e=>{e.preventDefault();if(!f.reportValidity())return;const d={...data(),id:'draft-'+Date.now()};localStorage.setItem(K,JSON.stringify([d,...read()]));status.textContent='Rascunho salvo.';setTimeout(()=>location.reload(),350)};root.querySelector('.publish-current').onclick=e=>{if(f.reportValidity())publish(data(),status,e.currentTarget)};root.querySelectorAll('[data-draft]').forEach(b=>b.onclick=()=>{Object.entries(read()[+b.dataset.draft]).forEach(([k,v])=>{if(f.elements[k])f.elements[k].value=v});gate()});root.querySelectorAll('[data-publish]').forEach(b=>b.onclick=()=>publish(read()[+b.dataset.publish],status,b))}
